toolScript:
const terminalLog = document.getElementById('terminal-log');
        const radar = document.getElementById('radar');
        const apiStatusText = document.getElementById('api-status-text');
        const apiDot = document.getElementById('api-dot');
        const btnErase = document.getElementById('btn-erase-action');
        const btnLock = document.getElementById('btn-lock-action');
        const btnCancel = document.getElementById('btn-cancel');
        const statusHeading = document.getElementById('status-heading');
        const statusDesc = document.getElementById('status-desc');
        let activeAbortController = null;
        // Initialize API Check
        window.addEventListener('DOMContentLoaded', () => {
            if ('NDEFReader' in window) {
                logMessage("Success: WebNFC API is supported on this device.", "success");
                apiStatusText.innerText = "API Available";
                apiStatusText.className = "text-[9px] font-bold text-emerald-600 uppercase tracking-tighter";
                apiDot.className = "w-2.5 h-2.5 bg-emerald-500 rounded-full";
            } else {
                logMessage("ERROR: WebNFC is not supported. Use Chrome on Android.", "error");
                document.getElementById('compatibility-banner').classList.remove('hidden');
                btnErase.disabled = true;
                btnLock.disabled = true;
                apiStatusText.innerText = "API Unavailable";
                apiStatusText.className = "text-[9px] font-bold text-red-600 uppercase tracking-tighter";
                apiDot.className = "w-2.5 h-2.5 bg-red-500 rounded-full";
            }
        });
        function logMessage(msg, type = "info") {
            const time = new Date().toLocaleTimeString('en-US', { hour12: false, hour: "numeric", minute: "numeric", second: "numeric" });
            const line = document.createElement('div');
            let color = "text-slate-400"; // default
            if (type === "success") color = "text-emerald-400";
            if (type === "error") color = "text-red-400";
            if (type === "warning") color = "text-amber-400";
            line.className = `mt-1 ${color}`;
            line.innerText = `[${time}] > ${msg}`;
            terminalLog.appendChild(line);
            terminalLog.scrollTop = terminalLog.scrollHeight;
        }
        function clearLog() {
            terminalLog.innerHTML = '<div class="text-slate-500">> Terminal cleared.</div>';
        }
        function uiScanningState(isScanning, type) {
            if (isScanning) {
                radar.classList.add('scanning');
                btnErase.disabled = true;
                btnLock.disabled = true;
                btnCancel.classList.remove('hidden');
                if (type === 'erase') {
                    statusHeading.innerText = "Scanning for Tag...";
                    statusDesc.innerText = "Hold your NFC tag against the back of your device to erase.";
                    statusHeading.className = "text-xl font-bold text-emerald-600 mb-2";
                } else {
                    statusHeading.innerText = "WARNING: Ready to Lock";
                    statusDesc.innerText = "Hold NFC tag to device. THIS ACTION IS PERMANENT.";
                    statusHeading.className = "text-xl font-bold text-amber-600 mb-2";
                }
            } else {
                radar.classList.remove('scanning');
                btnErase.disabled = false;
                btnLock.disabled = false;
                btnCancel.classList.add('hidden');
                statusHeading.innerText = "Ready to Scan";
                statusDesc.innerText = "Select an action below, then tap your NFC tag against the back of your device.";
                statusHeading.className = "text-xl font-bold text-slate-800 mb-2";
            }
        }
        async function startErase() {
            logMessage("Initializing ERASE protocol...", "info");
            try {
                activeAbortController = new AbortController();
                const ndef = new NDEFReader();
                uiScanningState(true, 'erase');
                logMessage("Please tap NFC tag now.", "warning");
                await ndef.write({ records: [] }, { signal: activeAbortController.signal });
                logMessage("SUCCESS: Empty NDEF record written. Tag is sanitized.", "success");
                showToast("Tag Erased Successfully");
                uiScanningState(false);
            } catch (error) {
                if (error.name === 'AbortError') {
                    logMessage("Operation cancelled by user.", "warning");
                } else {
                    logMessage(`WRITE FAILED: ${error.message}`, "error");
                    showToast("Error: " + error.name);
                }
                uiScanningState(false);
            }
        }
        async function startLock() {
            if (!confirm("Are you sure? Making a tag read-only is PERMANENT. It can NEVER be rewritten.")) {
                logMessage("Lock operation aborted by user.", "warning");
                return;
            }
            logMessage("Initializing LOCK protocol. Awaiting hardware...", "warning");
            try {
                activeAbortController = new AbortController();
                const ndef = new NDEFReader();
                uiScanningState(true, 'lock');
                logMessage("Please tap NFC tag now. Do not move the tag.", "warning");
                await ndef.makeReadOnly({ signal: activeAbortController.signal });
                logMessage("CRITICAL SUCCESS: Tag locked. Lock bits written.", "success");
                showToast("Tag Locked Permanently");
                uiScanningState(false);
            } catch (error) {
                if (error.name === 'AbortError') {
                    logMessage("Operation cancelled by user.", "warning");
                } else {
                    logMessage(`LOCK FAILED: ${error.message}`, "error");
                    showToast("Error: " + error.name);
                }
                uiScanningState(false);
            }
        }
        function cancelOperation() {
            if (activeAbortController) {
                activeAbortController.abort();
                activeAbortController = null;
            }
        }
        // --- Utility: Toast Notification ---
        function showToast(msg) {
            const toast = document.createElement('div');
            toast.className = "fixed top-24 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-8 py-3 rounded-full shadow-2xl z-[100] animate-fadeIn font-black text-xs uppercase tracking-widest border border-emerald-500";
            toast.innerText = msg;
            document.body.appendChild(toast);
            setTimeout(() => {
                toast.style.opacity = '0';
                toast.style.transition = 'opacity 0.5s ease';
                setTimeout(() => toast.remove(), 500);
            }, 3000);
        }
